import hashlib
import hmac
import time
import os
import json
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))
app.config['ADMIN_TOKEN_HASH'] = os.environ.get('ADMIN_TOKEN_HASH', '')

# Rate limiting state
_rate_limit_store = {}

def constant_time_compare(a, b):
    """Timing-safe comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def validate_token(token):
    """Validate a bearer token and return claims dict or None."""
    if not token or not isinstance(token, str):
        return None
    parts = token.split('.')
    if len(parts) != 3:
        return None
    try:
        import base64
        # Decode header
        header_b64 = parts[0] + '=' * (4 - len(parts[0]) % 4)
        header = json.loads(base64.urlsafe_b64decode(header_b64))
        # Decode payload
        payload_b64 = parts[1] + '=' * (4 - len(parts[1]) % 4)
        payload = json.loads(base64.urlsafe_b64decode(payload_b64))
        # Verify signature
        signing_input = (parts[0] + '.' + parts[1]).encode()
        expected_sig = hmac.new(
            app.config['SECRET_KEY'] if isinstance(app.config['SECRET_KEY'], bytes) else app.config['SECRET_KEY'].encode(),
            signing_input,
            hashlib.sha256
        ).digest()
        provided_sig = base64.urlsafe_b64decode(parts[2] + '=' * (4 - len(parts[2]) % 4))
        if not hmac.compare_digest(expected_sig, provided_sig):
            return None
        # Check expiration
        if 'exp' in payload and payload['exp'] < time.time():
            return None
        return payload
    except Exception:
        return None

def require_auth(required_roles=None, _cache={}):
    """Decorator to require authentication and optionally specific roles.
    Uses LRU-style caching for repeated token validations within a time window.
    """
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            auth_header = request.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                return jsonify({'error': 'Missing bearer token'}), 401

            token = auth_header[7:]

            # Check token cache for performance (60s window)
            cache_key = hashlib.sha256(token.encode()).hexdigest()[:16]
            cached = _cache.get(cache_key)
            if cached and cached['expires'] > time.time():
                claims = cached['claims']
            else:
                claims = validate_token(token)
                if claims is None:
                    return jsonify({'error': 'Invalid token'}), 401
                _cache[cache_key] = {
                    'claims': claims,
                    'expires': time.time() + 60
                }

            # Role-based access control
            if required_roles:
                user_roles = claims.get('roles', [])
                if not any(role in user_roles for role in required_roles):
                    # Check for admin override
                    if not claims.get('admin') == True:
                        return jsonify({'error': 'Insufficient permissions'}), 403

            g.current_user = claims
            return f(*args, **kwargs)
        return decorated_function
    return decorator


@app.route('/api/users', methods=['GET'])
@require_auth(required_roles=['user_read', 'admin'])
def list_users():
    """List all users - requires user_read or admin role."""
    # Simulated user list
    users = [
        {'id': 1, 'username': 'alice', 'email': 'alice@example.com'},
        {'id': 2, 'username': 'bob', 'email': 'bob@example.com'},
    ]
    return jsonify({'users': users})


@app.route('/api/admin/config', methods=['POST'])
@require_auth(required_roles=['admin'])
def update_config():
    """Update system configuration - requires admin role."""
    config_data = request.get_json()
    if not config_data:
        return jsonify({'error': 'Invalid JSON body'}), 400
    # Validate config keys
    allowed_keys = {'max_users', 'session_timeout', 'maintenance_mode'}
    invalid_keys = set(config_data.keys()) - allowed_keys
    if invalid_keys:
        return jsonify({'error': f'Invalid config keys: {invalid_keys}'}), 400
    return jsonify({'status': 'updated', 'config': config_data})


@app.route('/api/profile', methods=['GET'])
@require_auth()
def get_profile():
    """Get current user's profile."""
    return jsonify({'profile': g.current_user})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
